CREATE TRIGGER boards_timestamps_insert AFTER INSERT ON boards BEGIN UPDATE boards SET created_at=CASE WHEN NEW.created_at='' THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE NEW.created_at END,updated_at=CASE WHEN NEW.updated_at='' THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE NEW.updated_at END WHERE id=NEW.id; END;
CREATE TRIGGER boards_timestamps_update AFTER UPDATE ON boards WHEN NEW.version=OLD.version AND NEW.created_at=OLD.created_at BEGIN UPDATE boards SET version=OLD.version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.id; END;
CREATE TRIGGER columns_timestamps_insert AFTER INSERT ON columns BEGIN UPDATE columns SET created_at=CASE WHEN NEW.created_at='' THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE NEW.created_at END,updated_at=CASE WHEN NEW.updated_at='' THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE NEW.updated_at END WHERE id=NEW.id; END;
CREATE TRIGGER columns_timestamps_update AFTER UPDATE ON columns WHEN NEW.version=OLD.version AND NEW.created_at=OLD.created_at BEGIN UPDATE columns SET version=OLD.version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.id; END;
CREATE TRIGGER cards_timestamps_insert AFTER INSERT ON cards BEGIN UPDATE cards SET created_at=CASE WHEN NEW.created_at='' THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE NEW.created_at END,updated_at=CASE WHEN NEW.updated_at='' THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE NEW.updated_at END WHERE id=NEW.id; END;
CREATE TRIGGER cards_timestamps_update AFTER UPDATE ON cards WHEN NEW.version=OLD.version AND NEW.created_at=OLD.created_at BEGIN UPDATE cards SET version=OLD.version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.id; END;
